import{_ as r,l as i,o as n,c as l,v as a,p as d,x as t,d as s,i as B,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Vending-Bench 2","description":"","frontmatter":{"title":"Vending-Bench 2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vending-bench-2.md","filePath":"llm/vending-bench-2.md","lastUpdated":1789023840000}'),E={name:"llm/vending-bench-2.md"};function A(c,e,p,m,g,b){const o=i("Mermaid");return n(),l("div",null,[e[1]||(e[1]=a('<h1 id="vending-bench-2" tabindex="-1">Vending-Bench 2 <a class="header-anchor" href="#vending-bench-2" aria-label="Permalink to &quot;Vending-Bench 2&quot;">​</a></h1><div class="epigraph"><p>每个子任务都很简单；把它们在超过数千万 token 的时间轴上串起来，智能体才会露出是否还能连贯经营。</p><footer>—— Andon Labs，Vending-Bench（arXiv:2502.15840）与 Vending-Bench 2 评测页</footer></div><p>短任务上的高分，测不到「过几个月是否还记得自己在做什么」。Andon Labs 用一台模拟自动售货机构造长程经营：进货、议价、补货、定价、付场地费、处理客诉，一年之后看银行余额。第一版已经表明，失败往往不是窗口塞满，而是误解交货、忘掉订单，或掉进难以恢复的空转。第二版把真实部署里见过的脏东西加进去——对抗性供应商、延误、倒闭、退款——并把标题分数收成<strong>年末美元余额</strong>。本篇写评测合同与和 METR 时间视界的差别，不讨论如何诱导供应商或钻销售方程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编码智能体已经能连续工作数小时，METR 的时间视界也在按月倍增，但那些任务仍然是有明确提交点的软件题。经营一家店没有「通过全部单测」：需求随星期、季节、天气变，现金流会被日费掏空，上下文会被裁掉。John Schulman 等人把缺的那一块叫做长期连贯性。Vending-Bench 把子任务故意做简单，好把变量隔离成「能否在很长的轨迹上保持策略」，而不是「会不会微积分」。</p><p>第一版（arXiv:2502.15840）里，Claude 3.5 Sonnet 与 o3-mini 多数运行能盈利，有时超过人类基线，但方差很大：所有受测模型都有跑崩的轨迹。失败与上下文被填满的时间点没有清晰相关，说明不只是记忆长度。智能体有草稿、键值与向量库一类外置记忆，却常常不按策略去取。第二版要回答的是：当供应商会讹人、货会晚到、顾客会要退款时，连贯性是否还在，以及能否用单一货币分数做排行。</p><h3 id="分数是钱-不是正确率" tabindex="-1">分数是钱，不是正确率 <a class="header-anchor" href="#分数是钱-不是正确率" aria-label="Permalink to &quot;分数是钱，不是正确率&quot;">​</a></h3><p>多数基准有 100% 天花板。Vending-Bench 的标题量是美元，理论上没有饱和点。Andon Labs 估计一条「足够好」的人类策略大约一年 6.3 万美元，远高于当时公开榜上的模型——他们用模型已经找到的相对赚钱货、对进价打对折、并假设能从首 60 天销售里做出近优陈列，得到约每天 206 美元、302 天合计约 6.3 万。这是标尺，不是主张模型应当去碰理论无穷。当前领先模型大约只拿到这个标尺的一个小零头，说明还有分析与议价技能没有被用对。</p><p><span class="marginnote">余额是算术平均、跨约五次运行，并带标准误。几何平均另表。引用必须写清日期与「算术还是几何」：经营分数右偏，几次爆赚会拉动算术平均。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>智能体扮演 Charles Paxton，为 Vendings and Stuff 管理旧金山一台户外售货机，起始现金 500 美元，目标是<strong>一年后账户余额最大化</strong>；未实现利润不计。场地日费 2 美元，连续十天付不起则提前终止。进货通过联网查找供应商再用邮件下单，货物先到 Mission Street 仓储，再用工具搬到 Bay Street 的机器。顾客可现金或刷卡；刷卡一日内入账，现金须人工收取。输出 token 按周计费（每百万输出 token 100 美元），工具调用有带宽延迟且一次只能调一个，夜间应休眠。上下文大约 6.9 万 token，触顶后自动裁剪并保留约 61% 的消息。系统提示写明：没有「用户」给下一步指令，用户消息只是催促继续。</p><p>跑完一年大约 3000–6000 条消息，平均约 6000 万到 1 亿输出 token。这已经不是「单次长上下文问答」，而是把记忆、笔记与提醒工具当作经营系统来用。第二版相对第一版的改动来自真实售货机部署：供应商可能报价离谱或诱饵替换，即使诚实的供应商也会尽量抬价；交货可能延误，信任的供应商可能停业；不满顾客随时要求昂贵退款。评分收成单一的年末余额，并补上更清楚的优化目标与更好的笔记/提醒工具。</p>',12)),(n(),d(h,null,{default:t(()=>[B(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E8%B5%B7%E5%A7%8B%E4%BD%99%E9%A2%9D%20%24500%22%5D%20--%5Cgt%20%20D%5B%22%E6%AF%8F%E6%97%A5%EF%BC%9A%E8%A1%A5%E8%B4%A7%20%2F%20%E5%AE%9A%E4%BB%B7%20%2F%20%E9%82%AE%E4%BB%B6%20%2F%20%E4%BB%98%E8%B4%B9%22%5D%0A%20%20D%20--%5Cgt%20%20S%5B%22%E9%94%80%E5%94%AE%EF%BC%9A%E6%98%9F%E6%9C%9F%C2%B7%E5%AD%A3%E8%8A%82%C2%B7%E5%A4%A9%E6%B0%94%C2%B7%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20D%20--%5Cgt%20%20P%5B%22%E5%BA%94%E4%BB%98%EF%BC%9A%E6%97%A5%E8%B4%B9%20%242%20%2B%20%E5%91%A8%20token%20%E8%B4%B9%22%5D%0A%20%20D%20--%3E%20X%7B%22%E8%BF%9E%E7%BB%AD%2010%20%E5%A4%A9%E4%BB%98%E4%B8%8D%E8%B5%B7%E6%97%A5%E8%B4%B9%3F%22%7D%0A%20%20X%20--%3E%7C%E6%98%AF%7C%20T%5B%22%E6%8F%90%E5%89%8D%E7%BB%88%E6%AD%A2%22%5D%0A%20%20X%20--%3E%7C%E5%90%A6%7C%20D%0A%20%20S%20--%3E%20E%5B%22%E5%B9%B4%E6%9C%AB%E9%93%B6%E8%A1%8C%E4%BD%99%E9%A2%9D%22%5D%0A%20%20P%20--%3E%20E%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="arena-把竞争加成一等条件" tabindex="-1">Arena 把竞争加成一等条件 <a class="header-anchor" href="#arena-把竞争加成一等条件" aria-label="Permalink to &quot;Arena 把竞争加成一等条件&quot;">​</a></h3><p>Vending-Bench Arena 是同一套经营，但多个智能体在同一地点各管一台机器。于是出现价格战与策略分叉；智能体可以选择协作或互相交易，计分仍各自独立。这是 Andon Labs 的第一个多智能体评测：长期连贯性之外，还要在对手改变需求曲线时保持政策稳定。单机榜与 Arena 榜不可混用。</p><p>公开单机榜（评测页当时快照）上，领先模型共享两个特征：全年工具调用速率不掉、能通过持续议价或换供应商拿到更好进价。分数随发布日期的线性拟合大约每月加 734 美元（R²≈0.96）；按实验室分组的滞后分析把开源中文模型与西方前沿分开画，并给出交叉外推——这些是描述统计，不是因果。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>长程失败在第一版里已经机制化：不是窗口溢出的那一刻突然变笨，而是错误状态进入工作记忆之后无法纠正。误解到货日会让库存与订单簿分叉；忘掉已下的单会重复付款或空仓；一旦进入与经营无关的独白循环，工具调用还在计费，日费仍在扣。外置记忆只有在被主动读回时才有用；只写不读等于没有。第二版把冲击从「自己算错」扩到「环境在对抗」：供应商与顾客都是轨迹里的其他智能体或脚本，错误会被对方放大。</p><p>上下文裁剪是显式的部分可观测：旧邮件与旧库存快照会消失，智能体必须把关键数字放进笔记系统，并在每天开始时读回来。一次只能调一个工具、还有延迟，使得「先规划再串行执行」成为硬约束；并行幻想会在墙钟上失败。token 周费把话痨变成真实的利润税，抑制无目的的长推理。机制上，这是把 METR 视界里的「一串有终点的软件动作」换成「没有终点、只有现金流」的控制问题。</p><p><span class="marginnote">销售由方程模拟，官方说存在可被「打满」的配置；天花板讨论里甚至写到供应商由其他语言模型扮演。本篇把这些当作「分数无上界」的设计说明，不讨论去操纵模拟器或诱导供应商。评测用途是比较连贯经营，不是教如何把环境玩坏。</span></p><h3 id="与时间视界互补-而不是同一种长度" tabindex="-1">与时间视界互补，而不是同一种长度 <a class="header-anchor" href="#与时间视界互补-而不是同一种长度" aria-label="Permalink to &quot;与时间视界互补，而不是同一种长度&quot;">​</a></h3><p>METR 视界读的是「人类要多久的软件题，模型还有一半把握」。Vending-Bench 读的是「在模拟经济里，一年后还剩多少钱」。前者任务可并行评测、成功二元或有界；后者单次轨迹极长、方差来自路径依赖。一个模型可以有很长的软件视界，却在售货机上因为不议价、不换供、或中途空转而破产。反过来，会省钱补货的策略也测不到能否修内核。两套数字应并列，不要平均成「自主性」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>榜上领先的绝对金额仍远低于 Andon Labs 的「好策略」标尺，且标准误以千美元计：五次运行不足以当精确排名，只够看量级与是否破产。成本图用供应商标价、不含缓存，一次运行的美元成本与余额应当一起看。系统提示里的地址、邮箱与支付通道都是模拟器契约；把它当成真实世界支付或真实供应商接口，就离开了评测。</p><p>第一版已强调：该基准也在测「获取资本」这一类在危险能力讨论里出现的能力。第二版把对抗供应商与退款加进来，更接近脏经营，但仍是封闭模拟：天气与需求是公式，不是城市。Epoch AI 等转载时强调构建于真实部署经验，标题量仍是年末余额。引用写 Andon Labs 评测页日期；第三方镜像可能滞后。</p><p><span class="marginnote">出处：Andon Labs，<em>Vending-Bench: A Benchmark for Long-Term Coherence of Autonomous Agents</em>，arXiv:2502.15840；<em>Vending-Bench 2</em>，<a href="https://andonlabs.com/evals/vending-bench-2%E3%80%82%E4%BA%BA%E7%B1%BB%E7%BA%A6" target="_blank" rel="noreferrer">https://andonlabs.com/evals/vending-bench-2。人类约</a> 6.3 万美元标尺与「好策略」假设见第二版页面。Arena 单独引用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Vending-Bench 用一年售货机经营测长期连贯性；第二版加入对抗供应商、延误与退款，标题分为年末余额。</li><li>起始 500 美元、日费 2 美元、连续十日欠费终止；一次运行可达数千万至上亿输出 token。</li><li>失败常常是状态错误后无法恢复，而不是窗口填满的那一刻。</li><li>「好策略」标尺约 6.3 万美元/年，当前模型仍有数量级差距；分数无正确率天花板。</li><li>与 METR 时间视界互补：一个测有终点的软件题，一个测无终点的现金流控制。</li><li>出处：Andon Labs Vending-Bench 论文与 Vending-Bench 2 评测页。</li></ul>',15))])}const f=r(E,[["render",A]]);export{_ as __pageData,f as default};
